sys_script_include.script:
var FixScript = Class.create();
FixScript.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    initialize: function() {},


    //  to identify the orphan records in the instalation cmdb_sam_sw_install table
    cleanOrphanInstallation: function() {
        var orphanRecords = [];
        var encodedQuery = 'installed_onISEMPTY';
        //  encodedQuery = 'display_nameSTARTSWITHfilenet';

        try {
            var gr = new GlideRecord('cmdb_sam_sw_install');
            gr.addEncodedQuery(encodedQuery);
            gr.query();

            while (gr.next()) {
                // Collect the desired fields for each orphan record
                orphanRecords.push({
                    sys_id: gr.getUniqueValue(),
                    software_name: gr.getValue('display_name') // Assuming 'display_name' is the correct field
                });
            }
        } catch (error) {
            gs.error('Error occurred while cleaning orphan installations: ' + error.message);
            return (error.message);
        }

        return orphanRecords;
    },


    cleanOrphanSoftwareModel: function() {
        var results = {
            installCountZero: [],
            licenseCountZero: []
        };

        try {
            // Case 1: Query cmdb_software_product_model with install_count = 0
            var installGR = new GlideRecord('cmdb_software_product_model');
            installGR.addEncodedQuery('install_count=0'); // Encoded query for install_count = 0
            installGR.query();

            while (installGR.next()) {
                results.installCountZero.push({
                    sys_id: installGR.getUniqueValue(),
                    name: installGR.getValue('name')
                });
            }
        } catch (error) {
            gs.error('Error occurred while cleaning orphan installations: ' + error.message);

        }




        try {

            // Query licensable software models
            var softwareModelGR = new GlideRecord('cmdb_software_product_model');
            softwareModelGR.addEncodedQuery('sw_product_type=licensable');
            softwareModelGR.query();

            while (softwareModelGR.next()) {
                var softwareName = softwareModelGR.getValue('display_name');
                var softwareSysId = softwareModelGR.getUniqueValue();

                // Query the alm_license table for the current software model
                var installationGR = new GlideAggregate('alm_license');
                installationGR.addEncodedQuery('model.sys_id=' + softwareSysId); // Match by software_model sys_id
                installationGR.addAggregate('COUNT');
                installationGR.query();

                if (installationGR.next()) {
                    var licenseCount = parseInt(installationGR.getAggregate('COUNT'), 10);

                    // Log the details


                    // Add to results if the license count is zero
                    if (licenseCount === 0) {
                        results.licenseCountZero.push({
                            sys_id: softwareSysId,
                            name: softwareName
                        });
                    }
                }

                // Increment total processed
            }

            // Output the results

        } catch (error) {
            gs.error('Error occurred while processing software models: ' + error.message);
        }










        return results;
    },




    type: 'FixScript'
});
